34	const BASE_PREMIUMS: Record<string, number> = {
35	  sword: 100,
36	  amulet: 60,
37	  staff: 80,
38	  potion: 40,
39	  rune: 25,
40	  moonstone: 25,
41	};
42	
43	// Percentages are applied as integer arithmetic (× percent ÷ 100) rather than
44	// as a float rate (× 1.1): this keeps intermediate values integral and avoids
45	// binary floating-point error — 100 * 1.1 is 110.00000000000001, but
46	// (100 * 110) / 100 is exact.
47	const ONE_HUNDRED_PERCENT = 100;
48	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
49	const ADMIN_FEE = 5;
50	const LOYALTY_YEARS = 2;
51	const LOYALTY_DISCOUNT_PERCENT = 20;
52	
53	const applyPercent = (amount: number, percent: number): number =>
54	  (amount * percent) / ONE_HUNDRED_PERCENT;
55	
56	const addSurcharge = (amount: number, surchargePercent: number): number =>
57	  applyPercent(amount, ONE_HUNDRED_PERCENT + surchargePercent);
58	
59	const applyDiscount = (amount: number, discountPercent: number): number =>
60	  applyPercent(amount, ONE_HUNDRED_PERCENT - discountPercent);
61	
62	const COMPONENT_TYPES = ["rune", "moonstone"];
63	const BUILDING_BLOCK_SIZE = 3;
64	const BUILDING_BLOCK_BASE_PREMIUM = 60;
65	const isComponent = (item: Item): boolean => COMPONENT_TYPES.includes(item.type);
66	
67	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
68	
69	// Risk surcharges are per-item properties of the insured object, each raising
70	// that item's premium by a percentage. They stack multiplicatively: an item
71	// matching two rules is surcharged by the first, then by the second.
72	interface RiskSurcharge {
73	  appliesTo: (item: Item) => boolean;
74	  percent: number;
75	}
76	
77	const RISK_SURCHARGES: RiskSurcharge[] = [
78	  { appliesTo: (item) => item.cursed === true, percent: 50 },
79	  { appliesTo: (item) => (item.enchantment ?? 0) >= 5, percent: 30 },
80	];
81	
82	const riskAdjustedPremiumOf = (item: Item): number =>
83	  RISK_SURCHARGES.reduce(
84	    (premium, surcharge) =>
85	      surcharge.appliesTo(item) ? addSurcharge(premium, surcharge.percent) : premium,
86	    basePremiumOf(item),
87	  );
88	
89	const sumRiskAdjustedPremiums = (items: Item[]): number =>
90	  items.reduce((total, item) => total + riskAdjustedPremiumOf(item), 0);
91	
92	// Alike components are grouped into building blocks of 3, which carry a
93	// special base premium; the remaining components are priced individually,
94	// risk surcharges and all.
95	// Total over the empty group: no components means no blocks and no remainder.
96	const alikeComponentsPremium = (components: Item[]): number => {
97	  const blockCount = Math.floor(components.length / BUILDING_BLOCK_SIZE);
98	  const unblocked = components.slice(blockCount * BUILDING_BLOCK_SIZE);
99	  return (
100	    blockCount * BUILDING_BLOCK_BASE_PREMIUM + sumRiskAdjustedPremiums(unblocked)
101	  );
102	};
103	
104	const groupByType = (items: Item[]): Item[][] => [
105	  ...items
106	    .reduce(
107	      (groups, item) =>
108	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
109	      new Map<string, Item[]>(),
110	    )
111	    .values(),
112	];
113	
114	// Components and main items are priced by different rules, so each group is
115	// totalled separately: components by building block, main items item by item.
116	const componentsPremium = (components: Item[]): number =>
117	  groupByType(components).reduce(
118	    (total, alike) => total + alikeComponentsPremium(alike),
119	    0,
120	  );
121	
122	// The sum insured is what the items alone are worth to MHPCO, before any
123	// modifier that depends on the customer or the contract they sit in.
124	const sumInsuredOf = (items: Item[]): number =>
125	  sumRiskAdjustedPremiums(items.filter((item) => !isComponent(item))) +
126	  componentsPremium(items.filter(isComponent));
127	
128	// Contract-level modifiers adjust the sum insured by the terms of the deal
129	// rather than the nature of the items: the surcharge on a customer's first
130	// insurance, then the loyalty discount earned by long-standing customers.
131	const contractAdjustedPremiumOf = (
132	  sumInsured: number,
133	  customer: Customer,
134	): number => {
135	  const afterFirstInsurance = addSurcharge(
136	    sumInsured,
137	    FIRST_INSURANCE_SURCHARGE_PERCENT,
138	  );
139	  return customer.yearsWithMHPCO >= LOYALTY_YEARS
140	    ? applyDiscount(afterFirstInsurance, LOYALTY_DISCOUNT_PERCENT)
141	    : afterFirstInsurance;
142	};
143	
144	// Premiums round up in MHPCO's favour, and the flat admin fee is added last
145	// so that no percentage ever applies to it.
146	const billableFrom = (premium: number): number =>
147	  Math.ceil(premium) + ADMIN_FEE;
148	
149	const quote = (step: QuoteStep, customer: Customer): QuoteResult => ({
150	  premium: billableFrom(
151	    contractAdjustedPremiumOf(sumInsuredOf(step.items), customer),
152	  ),
153	});
154	
155	export const runScenario = (scenario: Scenario): ScenarioResult => ({
156	  results: scenario.steps.map((step) => quote(step, scenario.customer)),
157	});
