const roundedInMHPCOsFavour = (premium: number): number => Math.ceil(premium);

// The flat admin fee is added last so that no percentage ever applies to it.
const withAdminFee = (premium: number): number => premium + ADMIN_FEE;

const billedPremiumOf = (premium: number): number =>
  withAdminFee(roundedInMHPCOsFavour(premium));

const quote = (step: QuoteStep, customer: Customer): QuoteResult => ({
  premium: billedPremiumOf(
    contractAdjustedPremiumOf(sumInsuredOf(step.items), customer),
  ),
});

